/**
 * GENERATED FILE — the build-time mirror of data/policy_rules.json.
 *
 * Space compilation bundles TypeScript modules rather than raw JSON, so the
 * personal-loan credit policy records are mirrored here for the app to import,
 * exactly as data/personal-loans-data.ts mirrors data/personal_loans.json.
 * Regenerate this file whenever data/policy_rules.json changes — the two must
 * not drift.
 *
 * WHAT THIS DATA IS: Loanley's desk record of how each of 29 lenders actually
 * approves a personal loan, structured from the founder's lender policy
 * document — age band, salary floor by company category, employment vintage,
 * employer type and MCA vintage, FOIR, lock-in, foreclosure, part-payment,
 * top-up, balance-transfer and document rules. It supersedes the earlier
 * 19-lender PersonalLoan_RuleEngine workbook, which it covers in full; where
 * the workbook stated a different value, `sheetConflicts` records the
 * difference rather than dropping it.
 *
 * Lenders publish rate cards and almost never their approval rules, so none of
 * this is on a lender's website and none of it may be shown as a published
 * figure. Anything a borrower sees from here is labelled as Loanley's desk
 * policy, and rates, fees and costs still come only from the scraped rate cards.
 *
 * `null` always means the policy document does not state that value — never zero.
 */

export type PolicyEmploymentType = 'salaried' | 'self_employed';

/** One lender's personal-loan credit policy, as the policy document records it. */
export interface PolicyRuleRecord {
  /** Lender name as Loanley shows it. */
  lender: string;
  /** Join key into data/lenders.ts. */
  lenderId: string;
  /** False when the lender has policy rules on file but no rate card scraped yet. */
  inLenderDatabase: boolean;
  employmentTypes: PolicyEmploymentType[] | null;
  ageMin: number | null;
  ageMax: number | null;
  loanAmountMin: number | null;
  loanAmountMax: number | null;
  /** The LOWEST monthly salary floor in the policy — the most permissive band. */
  minSalaryMonthly: number | null;
  /** The salary rule in full, because most lenders vary it by company category. */
  minSalaryRule: string;
  tenureMinMonths: number | null;
  tenureMaxMonths: number | null;
  presentEmploymentMinMonths: number | null;
  totalEmploymentMinYears: number | null;
  /** Which employers the lender will fund, and any MCA vintage condition. */
  companyRule: string | null;
  companyMcaVintageYears: number | null;
  accommodationRule: string | null;
  /** Minimum bureau score, where the policy states one. */
  cibilMinScore: number | null;
  /** Whether an applicant with no credit history (CIBIL -1 / NH) is considered. */
  cibilMinusOneAccepted: boolean | null;
  /** Ceiling for a no-history applicant, where the policy caps one. */
  cibilMinusOneMaxAmount: number | null;
  /** Share of income total EMIs may consume, in the policy's own bands. */
  foirRule: string | null;
  lockingPeriod: string | null;
  foreclosureRule: string | null;
  partPaymentRule: string | null;
  topUpRule: string | null;
  /** Balance transfers accepted: 0 = not allowed, null = no limit stated. */
  balanceTransferMaxLoans: number | null;
  balanceTransferRule: string | null;
  /** Months of bank statements required on top of the standard document set. */
  bankStatementMonths: number | null;
  form16Required: boolean | null;
  /** Everything else the policy says about this lender, in its own terms. */
  specialFeatures: string[];
  /** Where the superseded rule-engine workbook stated something different. */
  sheetConflicts: string[];
}

export interface PolicyRuleSource {
  name: string;
  description: string;
  source: string;
  supersedes: string;
  sourceType: 'loanley_desk_policy_record';
  loanType: 'personal';
  currency: 'INR';
  /** How salary must reach the account at every lender in this record. */
  salaryCreditMode: string;
  /** Asked for by every lender; per-lender extras live on the record. */
  standardDocuments: string[];
  lenderCount: number;
}

/** Where these rules came from — quote this, never a lender's page. */
